mapper.select:
SELECT COUNT(DISTINCT t.id)
FROM efvs_training_experience t
INNER  JOIN efvs_file_upload f ON t.id = f.biz_id
INNER JOIN system_users u ON u.id = t.user_id
WHERE t.deleted = 0 and f.deleted = 0 and f.biz_id IS NOT NULL and t.tenant_id = #{param2} and f.tenant_id = #{param2}

    AND t.user_id = #{param3}


    AND t.training_theme LIKE CONCAT('%', #{param1.trainingTheme}, '%')


    AND t.training_time BETWEEN #{param1.trainingTime.begin} AND #{param1.trainingTime.end}


    AND t.training_location LIKE CONCAT('%', #{param1.trainingLocation}, '%')


    AND t.achieve_results = #{param1.achieveResults}


    AND t.training_teachers = #{param1.trainingTeachers}

SELECT te.id, te.user_id, te.process_instance_id, te.training_theme, te.training_time, te.training_location, te.training_duration, te.achieve_results, te.training_teachers, te.remark, IFNULL(JSON_ARRAYAGG( JSON_OBJECT( 'id', fu.id, 'bizId', fu.biz_id, 'fileName', fu.file_name, 'fileSize', fu.file_size, 'fileUrl', fu.file_url, 'fileAbsoluteUrl', fu.file_absolute_url, 'remark', fu.remark ) ), JSON_ARRAY()) AS fileList FROM efvs_training_experience te INNER JOIN efvs_file_upload fu ON te.id = fu.biz_id INNER JOIN system_users u ON u.id = te.user_id WHERE fu.biz_id IS NOT NULL AND fu.deleted = 0 AND fu.tenant_id = #{param4} AND te.deleted = 0 AND te.tenant_id = #{param4}
AND te.user_id = #{param5}
AND te.training_theme LIKE CONCAT('%', #{param1}, '%')
AND te.training_time BETWEEN #{param1.trainingTime.begin} AND #{param1.trainingTime.end}
AND te.training_location LIKE CONCAT('%', #{param1.trainingLocation}, '%')
AND te.achieve_results = #{param1.achieveResults}
AND te.training_teachers = #{param1.trainingTeachers}
GROUP BY te.id, te.user_id, te.process_instance_id, te.training_theme, te.training_time, te.training_location, te.training_duration, te.achieve_results, te.training_teachers, te.remark ORDER BY te.id DESC LIMIT #{param2}, #{param3}
